def hook(ctx, nb):
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    stage = nb.get('stage') or 'start'
    if p.get('unknown_column_error') or p.get('syntax_error') or (s.get('last_result_was_error') and (s.get('last_error_kind') in ('unknown_col', 'syntax') or 'exist' in (s.get('last_error_text') or ''))):
        stage = 'need_schema_probe'
        nb['fixing_unknown_column'] = bool(p.get('unknown_column_error'))
    elif p.get('last_result_empty') and not p.get('mutation_task'):
        stage = 'fixing_empty_result'
    elif p.get('repeated_sql') or (s.get('loop_streak') or 0) >= 2:
        stage = 'repeated_query_loop'
    elif p.get('text_only_loop') or (s.get('text_only_streak') or 0) >= 2:
        stage = 'text_numeric_handling'
    elif p.get('mutation_task') and p.get('mutation_not_attempted'):
        stage = 'mutation_needs_execution'
    elif p.get('mutation_task') and s.get('mutation_attempted'):
        stage = 'verify_mutation'
    elif p.get('candidate_answer_available') and not s.get('candidate_implausible'):
        stage = 'answer_shape_review'
    nb['stage'] = stage
    return None

def hook(ctx, nb):
    stage = nb.get('stage')
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Schema recovery: run SHOW TABLES, then DESCRIBE the exact table name with backticks. Use discovered column names exactly; do not replace spaces with underscores or use double quotes for identifiers.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty SELECT: inspect sample rows or distinct values for the filtered columns. Text fields may store numbers, punctuation, spaces, or percent signs, so relax one predicate at a time and cast only after confirming the stored format.'
    elif stage == 'text_numeric_handling':
        msg = 'Text numerics: for comparisons, ordering, min/max, or aggregates over TEXT columns, clean separators if needed and CAST to SIGNED or DECIMAL. Lexicographic ordering can give wrong results.'
    elif stage == 'mutation_needs_execution':
        msg = 'Mutation task: execute the INSERT, UPDATE, or DELETE before committing. In MySQL, quote identifiers with backticks and preserve requested literal text exactly, including currency symbols, spaces, punctuation, percent signs, and newlines.'
    elif stage == 'verify_mutation':
        msg = 'After a mutation, an empty tool result can still mean success. Verify the targeted row or count with SELECT, then commit a brief completion answer rather than treating [] as failure.'
    elif stage == 'answer_shape_review':
        msg = 'Before committing a SELECT answer, match the requested output shape: return the named entity or value requested, not an entire row unless the question asks for the whole record. If multiple rows are requested, submit separate answer entries.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

