    if a.get('tool') != 'commit_final_answer':
        return None
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    answers = a.get('answers') or []
    if p.get('commit_before_sql') or p.get('no_sql_yet'):
        return {'kind': 'block_and_prompt', 'message': 'Run at least one SQL query to inspect or modify the database before committing a final answer.'}
    if p.get('commit_empty_answer') and not (p.get('mutation_task') and s.get('mutation_attempted')):
        return {'kind': 'block_and_prompt', 'message': 'Do not commit an empty answer for a SELECT-style task. Use SQL evidence to provide the requested value or entity.'}
